{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-02",
  "sketch": {
    "components": ["Mobile app", "Deep link handler", "Payment confirmation screen", "Payment API"],
    "dataStores": [],
    "externalServices": [],
    "trustBoundaries": ["Untrusted website / other app -> mobile app deep link handler", "Mobile app -> payment backend"],
    "dataClasses": ["payment"],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Tampering",
      "title": "Any website can pre-fill a payment to the attacker's account and trick the user into confirming",
      "scenario": "An attacker hosts a page (or an ad, or a QR code) that opens myapp://pay?to=attacker&amount=500. The payment confirmation screen appears already filled in with the attacker's payee and amount, so a single tap by a user who thinks they are dismissing a popup sends money. Because the link is triggered cross-origin from an untrusted site, this is a request-forgery against the payment flow and can be mass-distributed.",
      "component": "Deep link handler -> Payment confirmation screen",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "The app registers a deep link myapp://pay?to= &amount= that opens the payment confirmation screen pre-filled. Any website can trigger the link." }
      ],
      "asvs": [],
      "cwe": ["CWE-352", "CWE-939"],
      "plainLanguage": "A random web page can open your payment screen with the attacker's details already typed in, so one tap pays them.",
      "requirement": {
        "title": "Payee and amount from a deep link must not be silently pre-filled as confirmable",
        "given": "a payment deep link arrives from an external source",
        "when": "the payment confirmation screen is opened",
        "then": "the app shows the payee and amount as unverified external input, requires the user to explicitly re-enter or re-confirm the amount and payee, and never allows a single tap to authorise the payment"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Deep link reaches the payment screen without re-authentication",
      "scenario": "The deep link jumps straight to the payment confirmation screen. An attacker with brief physical access to an unlocked phone, or a malicious app on the device, fires myapp://pay?to=...&amount=... and reaches a money-moving screen without passing device biometrics, app PIN or a fresh session check, then confirms the transfer.",
      "component": "Deep link handler",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "that opens the payment confirmation screen pre-filled" }
      ],
      "asvs": [],
      "cwe": ["CWE-306", "CWE-862"],
      "plainLanguage": "The link skips straight to paying, so nobody is asked to prove who they are first.",
      "requirement": {
        "title": "Step-up authentication before any deep-linked payment",
        "given": "a deep link targets the payment flow",
        "when": "the screen is presented and before the payment is submitted",
        "then": "the app requires a fresh step-up authentication (biometric or app PIN) and an authenticated, non-expired session, otherwise it routes the user to login instead of the payment screen"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Another app can claim the myapp:// scheme and intercept payment deep links",
      "scenario": "Custom URL schemes are not owned by one app. A malicious app installed on the same device registers myapp:// and receives the pay links instead, showing a cloned confirmation screen to harvest credentials or silently redirecting the payment. On Android an exported implicit intent filter also lets any local app launch the real payment screen directly.",
      "component": "myapp:// custom scheme registration",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "The app registers a deep link myapp://pay?to= &amount=" }
      ],
      "asvs": [],
      "cwe": ["CWE-939", "CWE-926"],
      "plainLanguage": "A fake app can grab the same link name and show a copycat payment screen.",
      "requirement": {
        "title": "Use verified app links instead of an unverified custom scheme",
        "given": "payment deep links are supported",
        "when": "a link is handled",
        "then": "the app accepts payment links only via domain-verified universal links / Android App Links (assetlinks.json, apple-app-site-association), and the custom myapp:// scheme either is removed for payment paths or is treated as fully untrusted with no pre-fill"
      }
    },
    {
      "stride": "Tampering",
      "title": "Unvalidated to and amount parameters from the URL",
      "scenario": "The to and amount values come straight from an attacker-controlled URL. Without strict validation an attacker can supply a negative, zero, huge or non-numeric amount, a differently formatted currency, or markup/control characters in the payee name to misrender the confirmation screen so the user sees a different payee or amount than the one that will actually be charged.",
      "component": "Deep link parameter parsing",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "myapp://pay?to= &amount= that opens the payment confirmation screen pre-filled" }
      ],
      "asvs": [],
      "cwe": ["CWE-20", "CWE-1289"],
      "plainLanguage": "The app trusts whatever payee and amount the link contains, so the screen can be made to show one thing and charge another.",
      "requirement": {
        "title": "Strict allow-list validation of deep link payment parameters",
        "given": "a payment deep link with to and amount parameters",
        "when": "the parameters are parsed",
        "then": "amount must match a strict decimal format within configured min/max limits, the payee must resolve to a known account via the backend, values are escaped before display, and any failure aborts the deep link with a generic error"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Payee and amount leak through browser history, referrers and device logs",
      "scenario": "Because the payment details are carried as query parameters in a URL triggered from the web, they are recorded in browser history, in the referring site's analytics, in OS/IDE device logs and in crash reports. Anyone with access to those artefacts (another app reading logs on older OS versions, a shared device, support tooling) learns who the user pays and how much.",
      "component": "myapp://pay URL parameters",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Any website can trigger the link." }
      ],
      "asvs": [],
      "cwe": ["CWE-532", "CWE-598"],
      "plainLanguage": "Putting payment details in a link means they get saved in histories and logs where other people can read them.",
      "requirement": {
        "title": "Do not persist payment parameters from deep links",
        "given": "a deep link containing payment parameters is handled",
        "when": "the app logs, reports a crash, or restores state",
        "then": "the to and amount values are redacted from all logs, analytics and crash reports, are cleared from the activity/intent and saved-state after parsing, and are never echoed into outbound URLs"
      }
    },
    {
      "stride": "Tampering",
      "title": "Overlay or tapjacking on the pre-filled confirmation screen",
      "scenario": "A malicious local app opens the pre-filled payment confirmation via the deep link and draws an overlay (or uses an accessibility service) on top of it, so the user's tap on an innocuous-looking button lands on Confirm. Because the amount and payee are already populated, no typing by the victim is needed to complete the payment.",
      "component": "Payment confirmation screen",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "opens the payment confirmation screen pre-filled" }
      ],
      "asvs": [],
      "cwe": ["CWE-1021"],
      "plainLanguage": "A bad app can cover the payment screen so your tap hits Confirm without you realising.",
      "requirement": {
        "title": "Overlay protection on the payment confirmation screen",
        "given": "the payment confirmation screen is displayed",
        "when": "another window overlays it or an accessibility/injected event is detected",
        "then": "the Confirm control is disabled (filterTouchesWhenObscured / hidden-window checks) and the payment cannot be submitted until the overlay is gone"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No record of which link or site initiated a payment, so disputes cannot be resolved",
      "scenario": "Payments can start from an arbitrary external website, but the design records nothing about the initiating deep link. When a victim disputes a transfer that was triggered by a malicious page, neither the user nor fraud operations can show that the payment originated from an untrusted deep link rather than from the user navigating in-app, so the fraud pattern stays invisible and is hard to reverse.",
      "component": "Payment submission / audit trail",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Any website can trigger the link." }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "If a scam link causes a payment, there is no proof it came from a link, making disputes hard.",
      "requirement": {
        "title": "Record deep link origin with every payment",
        "given": "a payment is submitted after arriving via a deep link",
        "when": "the app calls the payment API",
        "then": "it sends an initiation-source indicator (deep link, referring host if available, link id) which the backend stores immutably with the transaction and exposes to fraud review"
      }
    }
  ]
}

