      }
    },
    {
      "stride": "DenialOfService",
      "title": "Repeated deep links can hijack the app's screen and block normal use",
      "scenario": "A malicious page loads the myapp://pay link in a loop or from many iframes. The app is repeatedly brought to the foreground on the payment confirmation screen, interrupting whatever the user was doing, draining battery and potentially causing the user to tap confirm by accident while trying to dismiss the prompts.",
      "component": "Deep link handler foregrounding",
      "likelihood": 3,
      "impact": 2,
